  "what_i_need_from_you": [
    "Please provide one identifier I can use to look you up: your account email, your user ID, or your full name (case-sensitive).",
    "Tell me the amount you'd like to request — either the dollar increase (e.g., +$5,000) or the new total credit limit you want (e.g., $15,000).",
    "Confirm that you are the account owner or an authorized account manager for this card."
  ],
  "what_will_happen_next": "After you provide an identifier, I'll look up your account and ask you to confirm two verification fields (date of birth, email, phone number, or address). Once verified, I can submit the CLI request for you and let you know the next steps.",
  "offer": "If you'd rather speak with a human at any point, tell me and I can transfer you."
}

